import { relations } from "drizzle-orm";
import {
  boolean,
  index,
  integer,
  pgTable,
  text,
  timestamp,
  uniqueIndex,
} from "drizzle-orm/pg-core";

// ---------------------------------------------------------------------------
// Better Auth tables (generated by @better-auth/cli, admin + bearer plugins).
// Regenerate with: npx auth generate --config src/auth/auth.config.ts
// ---------------------------------------------------------------------------

export const user = pgTable(
  "user",
  {
    id: text("id").primaryKey(),
    name: text("name").notNull(),
    email: text("email").notNull().unique(),
    emailVerified: boolean("email_verified").default(false).notNull(),
    image: text("image"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .defaultNow()
      .$onUpdate(() => new Date())
      .notNull(),
    role: text("role"),
    banned: boolean("banned").default(false),
    banReason: text("ban_reason"),
    banExpires: timestamp("ban_expires"),
  },
  (table) => [index("user_email_idx").on(table.email)],
);

export const session = pgTable(
  "session",
  {
    id: text("id").primaryKey(),
    expiresAt: timestamp("expires_at").notNull(),
    token: text("token").notNull().unique(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .$onUpdate(() => new Date())
      .notNull(),
    ipAddress: text("ip_address"),
    userAgent: text("user_agent"),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    impersonatedBy: text("impersonated_by"),
  },
  (table) => [index("session_userId_idx").on(table.userId)],
);

export const account = pgTable(
  "account",
  {
    id: text("id").primaryKey(),
    accountId: text("account_id").notNull(),
    providerId: text("provider_id").notNull(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    accessToken: text("access_token"),
    refreshToken: text("refresh_token"),
    idToken: text("id_token"),
    accessTokenExpiresAt: timestamp("access_token_expires_at"),
    refreshTokenExpiresAt: timestamp("refresh_token_expires_at"),
    scope: text("scope"),
    password: text("password"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (table) => [index("account_userId_idx").on(table.userId)],
);

export const verification = pgTable(
  "verification",
  {
    id: text("id").primaryKey(),
    identifier: text("identifier").notNull(),
    value: text("value").notNull(),
    expiresAt: timestamp("expires_at").notNull(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .defaultNow()
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (table) => [index("verification_identifier_idx").on(table.identifier)],
);

// ---------------------------------------------------------------------------
// Domain tables (ported from the legacy Next app's SQL migrations).
// ---------------------------------------------------------------------------

export const roles = pgTable("roles", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  sortOrder: integer("sort_order").notNull().default(0),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
});

export const teams = pgTable(
  "teams",
  {
    id: text("id").primaryKey(),
    name: text("name").notNull(),
    sortOrder: integer("sort_order").notNull().default(0),
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [uniqueIndex("teams_name_unique").on(table.name)],
);

export const team = pgTable(
  "team",
  {
    id: text("id").primaryKey(),
    name: text("name").notNull(),
    role: text("role").notNull(),
    initials: text("initials").notNull(),
    gradient: text("gradient").notNull().default("from-violet-500 to-purple-500"),
    bio: text("bio").notNull().default(""),
    imageUrl: text("image_url"),
    userId: text("user_id").references(() => user.id, { onDelete: "set null" }),
    sortOrder: integer("sort_order").notNull().default(0),
    profileUrl: text("profile_url"),
    linkedinUrl: text("linkedin_url"),
    teamId: text("team_id").references(() => teams.id, { onDelete: "set null" }),
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [
    index("idx_team_user_id").on(table.userId),
    index("idx_team_team_id").on(table.teamId),
  ],
);

export const admins = pgTable("admins", {
  email: text("email").primaryKey(),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
});

export const appSettings = pgTable("app_settings", {
  key: text("key").primaryKey(),
  value: text("value"),
  updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow().notNull(),
});

export const projects = pgTable(
  "projects",
  {
    id: text("id").primaryKey(),
    name: text("name").notNull(),
    description: text("description"),
    appLink: text("app_link"),
    webLink: text("web_link"),
    liveLinkType: text("live_link_type"),
    projectTypes: text("project_types").array().notNull().default([]),
    skills: text("skills").array().notNull().default([]),
    sortOrder: integer("sort_order").notNull().default(0),
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [index("projects_sort_order_idx").on(table.sortOrder, table.createdAt)],
);

// ---------------------------------------------------------------------------
// Issued certificates — backs the public /verify/<id> lookup.
// ---------------------------------------------------------------------------

export const certificates = pgTable(
  "certificates",
  {
    id: text("id").primaryKey(),
    type: text("type").notNull(),
    recipientName: text("recipient_name").notNull(),
    programme: text("programme"),
    role: text("role"),
    startDate: text("start_date"),
    endDate: text("end_date"),
    issuedOn: text("issued_on").notNull(),
    summary: text("summary"),
    status: text("status").notNull().default("issued"),
    revokedOn: text("revoked_on"),
    revokedReason: text("revoked_reason"),
    /* Object key in the private certificates bucket. Nullable because a record
       can exist before its PDF is uploaded (and older rows have no file). */
    pdfKey: text("pdf_key"),
    pdfSize: integer("pdf_size"),
    pdfUploadedAt: timestamp("pdf_uploaded_at", { withTimezone: true }),
    /* Soft delete: a mistakenly-created record is hidden everywhere but kept,
       because the printed PDF may already be in circulation and an audit trail
       matters more than reclaiming the row. */
    deletedAt: timestamp("deleted_at", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [
    index("certificates_type_idx").on(table.type),
    index("certificates_issued_on_idx").on(table.issuedOn),
    index("certificates_deleted_at_idx").on(table.deletedAt),
  ],
);

// ---------------------------------------------------------------------------
// Surveyor registry — the field network behind Kavi Survey & Research.
// ---------------------------------------------------------------------------

export const SURVEYOR_STATUSES = ["applied", "verified", "active", "inactive", "rejected"] as const;
export type SurveyorStatus = (typeof SURVEYOR_STATUSES)[number];

export const surveyors = pgTable(
  "surveyors",
  {
    id: text("id").primaryKey(),
    name: text("name").notNull(),
    email: text("email").notNull(),
    phone: text("phone").notNull(),
    /* Where the surveyor can physically work. Free text because coverage is
       usually "Warangal + 3 neighbouring districts" rather than a lookup code. */
    location: text("location").notNull().default(""),
    languages: text("languages").array().notNull().default([]),
    skills: text("skills").array().notNull().default([]),
    experience: text("experience").notNull().default(""),
    notes: text("notes").notNull().default(""),
    status: text("status").notNull().default("applied"),
    verifiedAt: timestamp("verified_at", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [
    index("surveyors_status_idx").on(table.status),
    index("surveyors_location_idx").on(table.location),
    /* One profile per email: a repeat registration updates the existing record
       instead of creating duplicates in the network. */
    uniqueIndex("surveyors_email_unique").on(table.email),
  ],
);

// ---------------------------------------------------------------------------
// Relations
// ---------------------------------------------------------------------------

export const userRelations = relations(user, ({ many }) => ({
  sessions: many(session),
  accounts: many(account),
}));

export const sessionRelations = relations(session, ({ one }) => ({
  user: one(user, {
    fields: [session.userId],
    references: [user.id],
  }),
}));

export const accountRelations = relations(account, ({ one }) => ({
  user: one(user, {
    fields: [account.userId],
    references: [user.id],
  }),
}));

export const teamRelations = relations(team, ({ one }) => ({
  user: one(user, {
    fields: [team.userId],
    references: [user.id],
  }),
  team: one(teams, {
    fields: [team.teamId],
    references: [teams.id],
  }),
}));

export const teamsRelations = relations(teams, ({ many }) => ({
  members: many(team),
}));

export type UserRow = typeof user.$inferSelect;
export type SessionRow = typeof session.$inferSelect;
export type TeamRow = typeof team.$inferSelect;
export type TeamInsert = typeof team.$inferInsert;
export type OrgRoleRow = typeof roles.$inferSelect;
export type OrgTeamRow = typeof teams.$inferSelect;
export type AdminRow = typeof admins.$inferSelect;
export type AppSettingRow = typeof appSettings.$inferSelect;
export type ProjectRow = typeof projects.$inferSelect;
export type ProjectInsert = typeof projects.$inferInsert;
export type CertificateRow = typeof certificates.$inferSelect;
export type CertificateInsert = typeof certificates.$inferInsert;
export type SurveyorRow = typeof surveyors.$inferSelect;
export type SurveyorInsert = typeof surveyors.$inferInsert;
